import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.ChIlRNAd.js";const g=JSON.parse('{"title":"Cleanup","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/cleanup.md","filePath":"en/guide/cleanup.md"}'),r={name:"en/guide/cleanup.md"};function o(i,e,l,d,h,c){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="cleanup" tabindex="-1">Cleanup <a class="header-anchor" href="#cleanup" aria-label="Permalink to &quot;Cleanup&quot;">​</a></h1><p>The <strong>Cleanup</strong> page (<code>/cleanup</code>) frees space in a few clicks. Its header sums up the possible gain: &quot;6.1 GB to reclaim. The top 8 senders weigh 4.6 GB.&quot;</p><p>Two tabs: <strong>Senders &amp; newsletters</strong> and <strong>Large mails &amp; attachments</strong>.</p><hr><h2 id="senders-newsletters" tabindex="-1">Senders &amp; newsletters <a class="header-anchor" href="#senders-newsletters" aria-label="Permalink to &quot;Senders &amp; newsletters&quot;">​</a></h2><h3 id="scan-the-mailbox" tabindex="-1">Scan the mailbox <a class="header-anchor" href="#scan-the-mailbox" aria-label="Permalink to &quot;Scan the mailbox&quot;">​</a></h3><p>On the first visit: &quot;This account has not been scanned yet&quot;. Click <strong>Scan the mailbox</strong>: Nid groups mailing-list and newsletter mails by sender. The scan runs in the background; you can leave the page.</p><p>Afterwards, the date of the last scan shows (&quot;Scanned on …&quot;) with <strong>Scan again</strong>.</p><h3 id="sender-list" tabindex="-1">Sender list <a class="header-anchor" href="#sender-list" aria-label="Permalink to &quot;Sender list&quot;">​</a></h3><p>For each sender: <strong>Sender</strong>, <strong>Address</strong>, <strong>Size</strong>, <strong>Mails</strong>, <strong>Never opened</strong>, and its actions.</p><ul><li><strong>Sort by</strong>: <strong>Number of mails</strong>, <strong>Size</strong> or <strong>Never opened</strong>.</li><li><strong>Newsletters only (List-Unsubscribe)</strong>: keeps only senders that offer an automatic unsubscribe.</li></ul><p>Sorting and filter are kept in the page address.</p><h3 id="actions-on-a-sender" tabindex="-1">Actions on a sender <a class="header-anchor" href="#actions-on-a-sender" aria-label="Permalink to &quot;Actions on a sender&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Unsubscribe and clean up</strong></td><td>unsubscribes, then moves all its mails to the Gmail trash</td></tr><tr><td><strong>Delete all</strong></td><td>moves all its mails to the Gmail trash, without unsubscribing</td></tr><tr><td><strong>Always do this</strong></td><td>opens the <a href="./rules.html#create-a-rule">rule</a> form prefilled with the sender, to also handle its future mails</td></tr></tbody></table><p>On mobile, a card&#39;s <code>⋯</code> button opens these actions in a panel.</p><h4 id="unsubscribe-and-clean-up" tabindex="-1">Unsubscribe and clean up <a class="header-anchor" href="#unsubscribe-and-clean-up" aria-label="Permalink to &quot;Unsubscribe and clean up&quot;">​</a></h4><p>A confirmation shows: &quot;Unsubscribe from {sender}?&quot;. The sender&#39;s unsubscribe page opens in a new tab: <strong>unsubscribing is final</strong>. Its mails then go to the Gmail trash.</p><p>If the sender provides no <code>List-Unsubscribe</code> header, the button is disabled with the note &quot;This sender offers no automatic unsubscribe&quot;; <strong>Delete all</strong> and <strong>Always do this</strong> stay available.</p><h4 id="undo-and-progress" tabindex="-1">Undo and progress <a class="header-anchor" href="#undo-and-progress" aria-label="Permalink to &quot;Undo and progress&quot;">​</a></h4><p>Deleting the mails (after unsubscribing or with <strong>Delete all</strong>) shows the toast &quot;Deleting N emails in 10 s&quot; with <strong>Undo</strong>, as in <a href="./mails.html#undo">Mail</a>. Progress then shows on the sender&#39;s row, with <strong>Stop</strong>. The task is also listed in <a href="./activity.html">Activity</a>.</p><hr><h2 id="large-mails-attachments" tabindex="-1">Large mails &amp; attachments <a class="header-anchor" href="#large-mails-attachments" aria-label="Permalink to &quot;Large mails &amp; attachments&quot;">​</a></h2><p>The account&#39;s heaviest attachments, sorted by size. The summary reads &quot;N attachments · size&quot;.</p><p><strong>Source</strong>:</p><ul><li><strong>Gmail</strong>: Gmail mails with an attachment over 100 KB. Tick rows to <strong>Save to the NAS</strong> or <strong>Delete</strong> the matching mails (deletion can be undone for 10 s).</li><li><strong>Archives (NAS)</strong>: attachments already archived. Those mails are no longer handled here; download only.</li></ul><p>Columns: <strong>File</strong>, <strong>Mail</strong> (subject), <strong>Size</strong>, <strong>Date</strong>, and a download button.</p><p>For every attachment, with search and paging, see the <a href="./attachments.html">Attachments</a> page.</p>',27)])])}const p=t(r,[["render",o]]);export{g as __pageData,p as default};
